/** @type {import('tailwindcss').Config} */
// CommonJS config file, so require is the right way to load the palette here
// eslint-disable-next-line @typescript-eslint/no-require-imports
const colors = require("tailwindcss/colors");

// Every neutral and accent colour reads from a CSS variable defined in src/app/theme.css
// (generated by scripts/generate-theme.mjs), so the whole UI switches between light and dark
// by toggling the `dark` class on <html>. Keep these lists in sync with the generator.
const NEUTRALS = ["slate", "gray"];
const HUES = ["red", "orange", "amber", "yellow", "lime", "green", "emerald", "teal", "cyan", "sky", "blue", "indigo", "violet", "purple", "fuchsia", "pink", "rose"];

const themed = name => `rgb(var(--tw-c-${name}) / <alpha-value>)`;
const family = name => Object.fromEntries(Object.keys(colors[name]).map(shade => [shade, themed(`${name}-${shade}`)]));

module.exports = {
  darkMode: "class",
  content: [
    "./src/pages/**/*.{js,ts,jsx,tsx,mdx}",
    "./src/components/**/*.{js,ts,jsx,tsx,mdx}",
    "./src/app/**/*.{js,ts,jsx,tsx,mdx}",
  ],
  theme: {
    colors: {
      transparent: "transparent",
      current: "currentColor",
      inherit: "inherit",
      white: themed("white"),
      black: themed("black"),
      // Families the UI doesn't use stay as plain Tailwind colours
      zinc: colors.zinc,
      neutral: colors.neutral,
      stone: colors.stone,
      ...Object.fromEntries([...NEUTRALS, ...HUES].map(name => [name, family(name)])),
    },
    extend: {},
  },
  plugins: [],
};
